    def register_host_network_route(
        self,
        method: str,
        path: str,
        host_bridge: Any,
        *,
        persisted_payload_builder: Optional[PersistedPayloadBuilder] = None,
        host_response_projector: Optional[HostResponseProjector] = None,
        coalesce_active: bool = False,
        require_live_account: bool = True,
        require_execution_owner: bool = True,
    ) -> None:
        """Register a host transport adapter behind shared operation semantics."""

        if host_bridge is None or not hasattr(
            host_bridge,
            "executeNetworkOperation",
        ):
            raise TypeError("host bridge does not expose executeNetworkOperation")
        if not hasattr(host_bridge, "executionOwnerActive"):
            raise TypeError("host bridge does not expose executionOwnerActive")
        route_method = str(method).upper()
        route_path = str(path).split("?", 1)[0]
        _key, route = self._declared_route(route_method, route_path)
        mutation = str(route.get("operationKind") or "") == "mutation"
        if mutation and (
            not hasattr(host_bridge, "tryAcquireNetworkOperation")
            or not hasattr(host_bridge, "releaseNetworkOperation")
        ):
            raise TypeError(
                "mutation host bridge requires two-phase account lock methods"
            )

        def hosted_handler(
            body: Dict[str, Any],
            context: Dict[str, Any],
            execution: OperationExecutionContext,
        ) -> Dict[str, Any]:
            account_ref = self._account_ref(body, context)
            if require_live_account:
                self._require_live_account_for_host_operation(account_ref)
            execution.publish_progress(
                5,
                {"phase": "waiting-for-account-lane-or-game-server"},
            )
            busy_backoff = HOST_ACCOUNT_BUSY_INITIAL_BACKOFF_SECONDS
            host_lock_acquired = False
            try:
                while True:
                    if (
                        require_execution_owner
                        and not bool(host_bridge.executionOwnerActive())
                    ):
                        raise OperationDeferredError(
                            "Android 前台执行所有者未激活，已拒绝游戏网络请求"
                        )
                    execution.raise_if_cancelled()
                    if mutation and not host_lock_acquired:
                        host_lock_acquired = bool(
                            host_bridge.tryAcquireNetworkOperation(account_ref)
                        )
                        if not host_lock_acquired:
                            execution.wait(busy_backoff)
                            busy_backoff = min(
                                busy_backoff * 2,
                                HOST_ACCOUNT_BUSY_MAX_BACKOFF_SECONDS,
                            )
                            continue
                        # Recheck cancellation and live ownership after taking the
                        # JVM scheduler lock but before crossing the irreversible line.
                        execution.raise_if_cancelled()
                        if (
                            require_execution_owner
                            and not bool(host_bridge.executionOwnerActive())
                        ):
                            raise OperationDeferredError(
                                "Android 前台执行所有者已停止，未发送游戏请求"
                            )
                        execution.mark_request_sent({
                            "method": route_method,
                            "path": route_path,
                            "transport": "android-host",
                        })
                    host_context = {
                        **context,
                        "operationId": execution.operation_id,
                    }
                    raw_response = host_bridge.executeNetworkOperation(
                        route_method,
                        route_path,
                        self._json(body),
                        self._json(host_context),
                    )
                    try:
                        response = json.loads(str(raw_response or "{}"))
                    except json.JSONDecodeError as error:
                        raise RuntimeError(
                            "host network adapter returned invalid JSON"
                        ) from error
                    if not isinstance(response, dict):
                        raise RuntimeError(
                            "host network adapter response must be an object"
                        )
                    status = int(response.get("status") or 500)
                    response_body = response.get("body")
                    if not isinstance(response_body, dict):
                        raise RuntimeError(
                            "host network adapter body must be an object"
                        )
                    self._assert_no_sensitive_values(response_body)
                    response_code = str(response_body.get("code") or "")
                    if response_code == HOST_ACCOUNT_BUSY_CODE:
                        if mutation:
                            raise OperationKnownFailureError(
                                "mutation adapter reported busy after lock acquisition",
                                code="HOST_LOCK_CONTRACT_FAILED",
                            )
                        execution.wait(busy_backoff)
                        busy_backoff = min(
                            busy_backoff * 2,
                            HOST_ACCOUNT_BUSY_MAX_BACKOFF_SECONDS,
                        )
                        continue
                    if not 200 <= status < 300 or response_body.get("ok") is False:
                        raise OperationKnownFailureError(
                            str(
                                response_body.get("error")
                                or response_body.get("message")
                                or f"host network adapter failed with status {status}"
                            ),
                            code=response_code or "HOST_OPERATION_FAILED",
                            details={"httpStatus": status},
                        )
                    break
            finally:
                if host_lock_acquired:
                    host_bridge.releaseNetworkOperation(account_ref)
            if host_response_projector is not None:
                response_body = self._object(
                    host_response_projector(
                        dict(response_body),
                        dict(body),
                        dict(context),
                    ),
                    "projected host operation response",
                )
                self._assert_no_sensitive_values(response_body)
            execution.publish_progress(90, {"phase": "persisting-result"})
            return dict(response_body)

        self.register_network_route(
            route_method,
            route_path,
            hosted_handler,
            persisted_payload_builder=persisted_payload_builder,
            coalesce_active=coalesce_active,
            runnable_when=(
                (lambda: _host_network_lane_ready(host_bridge))
                if require_execution_owner
                else (lambda: True)
            ),
        )

    def register_host_game_command_route(
        self,
        method: str,
        path: str,
        host_bridge: Any,
        workflow: Callable[
            [OperationExecutionContext, Dict[str, Any], Dict[str, Any]],
            Dict[str, Any],
        ],
        *,
        persisted_payload_builder: PersistedPayloadBuilder,
        coalesce_active: bool = True,
    ) -> None:
        """Register a Python-owned workflow over a host byte transport."""

        has_python_raw_transport = (
            self._ports.raw_http is not None
            and self._ports.session_secrets is not None
        )
        if not has_python_raw_transport and self._ports.game_commands is None:
            raise TypeError("host does not expose a shared game byte transport")
        if not hasattr(host_bridge, "executionOwnerActive"):
            raise TypeError("host bridge does not expose executionOwnerActive")
        if (
            not hasattr(host_bridge, "tryAcquireNetworkOperation")
            or not hasattr(host_bridge, "releaseNetworkOperation")
        ):
            raise TypeError("raw game mutation requires two-phase account lock methods")
        if not callable(workflow):
            raise TypeError("raw game workflow must be callable")
        route_method = str(method).upper()
        route_path = str(path).split("?", 1)[0]

        def game_workflow_handler(
            body: Dict[str, Any],
            context: Dict[str, Any],
            execution: OperationExecutionContext,
        ) -> Dict[str, Any]:
            account_ref = self._account_ref(body, context)
            self._require_live_account_for_host_operation(account_ref)
            execution.publish_progress(
                5,
                {"phase": "waiting-for-account-lane"},
            )
            busy_backoff = HOST_ACCOUNT_BUSY_INITIAL_BACKOFF_SECONDS
            acquired = False
            try:
                while not acquired:
                    if not bool(host_bridge.executionOwnerActive()):
                        raise OperationDeferredError(
                            "Android 前台执行所有者未激活，已拒绝游戏网络请求"
                        )
                    execution.raise_if_cancelled()
                    acquired = bool(
                        host_bridge.tryAcquireNetworkOperation(account_ref)
                    )
                    if not acquired:
                        execution.wait(busy_backoff)
                        busy_backoff = min(
                            busy_backoff * 2,
                            HOST_ACCOUNT_BUSY_MAX_BACKOFF_SECONDS,
                        )
                execution.raise_if_cancelled()
                if not bool(host_bridge.executionOwnerActive()):
                    raise OperationDeferredError(
                        "Android 前台执行所有者已停止，未发送游戏请求"
                    )
                return workflow(execution, dict(body), dict(context))
            finally:
                if acquired:
                    host_bridge.releaseNetworkOperation(account_ref)

        self.register_network_route(
            route_method,
            route_path,
            game_workflow_handler,
            persisted_payload_builder=persisted_payload_builder,
            coalesce_active=coalesce_active,
            runnable_when=lambda: _host_network_lane_ready(host_bridge),
        )

    def dispatch(
        self,
        method: str,
        path: str,
        body: Optional[Dict[str, Any]] = None,
        request_context: Optional[Dict[str, Any]] = None,
    ) -> CoreResponse:
        try:
            normalized_body = self._object(body or {}, "request body")
            context = self._object(
                request_context or {},
                "request context",
            )
        except ValueError as error:
            return self._error(400, "INVALID_REQUEST", str(error))

        key = self._route_key(method, path)
        route = self._route_index.get(key)
        if route is None:
            return self._error(
                404,
                "ROUTE_NOT_DECLARED",
                f"shared core route is not declared: {key[0]} {key[1]}",
            )
        if route["responseClass"] == "local":
            handler = self._local_handlers.get(key)
            if handler is None:
                return self._not_migrated(key, route)
            try:
                return self._normalize_handler_response(
                    handler(normalized_body, context)
                )
            except ValueError as error:
                return self._error(400, "LOCAL_VALIDATION_FAILED", str(error))
            except Exception as error:
                self._log_exception(key, error)
                return self._error(
                    500,
                    "LOCAL_HANDLER_FAILED",
                    str(error) or error.__class__.__name__,
                )

        registration = self._network_handlers.get(key)
        if registration is None:
            return self._not_migrated(key, route)
        account_ref = self._account_ref(normalized_body, context)
        if not account_ref:
            return self._error(
                400,
                "ACCOUNT_REF_REQUIRED",
                "network operation requires accountRef",
            )
        idempotency_key = self._idempotency_key(normalized_body, context)
        if not idempotency_key:
            return self._error(
                400,
                "IDEMPOTENCY_KEY_REQUIRED",
                "network operation requires idempotencyKey or requestId",
            )
        try:
            payload_builder = registration.get("payloadBuilder")
            if payload_builder is None:
                self._assert_no_sensitive_values(normalized_body)
                persisted_body = dict(normalized_body)
            else:
                persisted_body = self._object(
                    payload_builder(normalized_body, context),
                    "persisted operation payload",
                )
                self._assert_no_sensitive_values(persisted_body)
            persisted_context = {
                key_name: context[key_name]
                for key_name in (
                    "requestId",
                    "source",
                    "platform",
                )
                if key_name in context
            }
            submission = self.submit_network_operation(
                account_ref=account_ref,
                operation_type=str(registration["operationType"]),
                operation_kind=str(registration["kind"]),
                payload={
                    "body": persisted_body,
                    "requestContext": persisted_context,
                },
                idempotency_key=idempotency_key,
                coalesce_active=(
                    str(registration["operationType"]) == "query"
                    or bool(registration.get("coalesceActive"))
                ),
            )
            return CoreResponse(202, submission)
        except ValueError as error:
            return self._error(400, "NETWORK_OPERATION_REJECTED", str(error))
        except Exception as error:
            self._log_exception(key, error)
            return self._error(
                500,
                "NETWORK_OPERATION_SUBMIT_FAILED",
                str(error) or error.__class__.__name__,
            )

    def dispatch_json(
        self,
        method: str,
        path: str,
        body_json: str = "{}",
        request_context_json: str = "{}",
    ) -> str:
        try:
            body = json.loads(body_json or "{}")
            context = json.loads(request_context_json or "{}")
        except json.JSONDecodeError as error:
            response = self._error(400, "INVALID_JSON", str(error))
        else:
            response = self.dispatch(method, path, body, context)
        return self._json(response.to_dict())

    def dispatch_local(
        self,
        method: str,
        path: str,
        body: Optional[Dict[str, Any]] = None,
    ) -> CoreResponse:
        """Compatibility alias retained while desktop handlers migrate."""

        route = self.route_metadata(method, path)
        if route is not None and route.get("responseClass") != "local":
            return self._error(
                409,
                "NETWORK_ROUTE_REQUIRES_ASYNC_DISPATCH",
                "network route cannot run through dispatch_local",
            )
        return self.dispatch(method, path, body, {})

    def submit_network_operation(
        self,
        account_ref: str,
        operation_type: str,
        operation_kind: str,
        payload: Dict[str, Any],
        idempotency_key: str,
        coalesce_active: bool = False,
    ) -> Dict[str, Any]:
        return self._operations.submit_network(
            account_ref=account_ref,
            operation_type=operation_type,
            kind=operation_kind,
            idempotency_key=idempotency_key,
            payload=payload,
            coalesce_active=coalesce_active,
        )

    def submit_simulated_network_operation(
        self,
        duration_millis: int,
        idempotency_key: str,
        payload: Optional[Dict[str, Any]] = None,
    ) -> Dict[str, Any]:
        """Submit a durable delayed operation which performs no network I/O."""

        return self._operations.submit_simulated(
            duration_millis,
            idempotency_key,
            payload,
        )

    def submit_simulated_network_operation_json(
        self,
        duration_millis: int,
        idempotency_key: str,
        payload_json: str = "{}",
    ) -> str:
        payload = json.loads(payload_json or "{}")
        if not isinstance(payload, dict):
            raise ValueError("simulated operation payload must be an object")
        return self._json(
            self.submit_simulated_network_operation(
                duration_millis,
                idempotency_key,
                payload,
            )
        )

    def operation_status(
        self,
        operation_id: str,
        wait_millis: int = 0,
    ) -> Dict[str, Any]:
        budget = max(0, int(wait_millis or 0))
        if budget > 0:
            operation = self._operations.await_status(operation_id, budget)
        else:
            operation = self._operations.status(operation_id)
        if operation is None:
            return {"ok": False, "error": "operation not found"}
        return {"ok": True, "operation": operation}

    def operation_status_json(
        self,
        operation_id: str,
        wait_millis: int = 0,
    ) -> str:
        return self._json(self.operation_status(operation_id, wait_millis))

    def operations_snapshot(self) -> Dict[str, Any]:
        operations = self._operations.list_operations()
        return {
            "ok": True,
            "operations": operations,
            "count": len(operations),
        }

    def operations_snapshot_json(self) -> str:
        return self._json(self.operations_snapshot())

    def cancel_operation(self, operation_id: str) -> Dict[str, Any]:
        operation = self._operations.cancel(operation_id)
        if operation is None:
            return {"ok": False, "error": "operation not found"}
        return {"ok": True, "operation": operation}

    def cancel_operation_json(self, operation_id: str) -> str:
        return self._json(self.cancel_operation(operation_id))

    def protocol_fixture_report(self) -> Dict[str, Any]:
        return verify_protocol_fixtures()

    def protocol_fixture_report_json(self) -> str:
        return self._json(self.protocol_fixture_report())

    def close(self) -> None:
        self._operations.close()

    def _resolve_operation_store_path(
        self,
        operation_store_path: Optional[str],
    ) -> Optional[Path]:
        if operation_store_path:
            return Path(operation_store_path)
        data_port = self._ports.data_directory
        if data_port is None:
            return None
        return data_port.data_directory() / "shared_core" / "operations-v2.json"

    def _resolve_account_store_path(
        self,
        account_store_path: Optional[str],
        operation_store_path: Optional[Path],
    ) -> Optional[Path]:
        if account_store_path:
            return Path(account_store_path)
        if operation_store_path is not None:
            return operation_store_path.parent / "accounts-v1.json"
        data_port = self._ports.data_directory
        if data_port is None:
            return None
        return data_port.data_directory() / "shared_core" / "accounts-v1.json"

    def _health_route(
        self,
        body: Dict[str, Any],
        context: Dict[str, Any],
    ) -> Dict[str, Any]:
        return self.health()

    def _accounts_route(
        self,
        body: Dict[str, Any],
        context: Dict[str, Any],
    ) -> Dict[str, Any]:
        runtime_by_account = body.get("runtimeByAccount") or {}
        if not isinstance(runtime_by_account, dict):
            raise ValueError("runtimeByAccount must be an object")
        account_refs = body.get("accountRefs")
        if account_refs is not None and not isinstance(account_refs, list):
            raise ValueError("accountRefs must be an array")
        summary_only = bool(body.get("summary", False))
        snapshot = self._accounts.presentation_snapshot()
        cards = project_account_cards(
            snapshot["accounts"],
            runtime_by_account,
            self._account_lifecycle,
            execution_owner_active=bool(
                context.get("executionOwnerActive", False)
            ),
            now_millis=int(
                context.get("nowMillis")
                or self._ports.clock.now_millis()
            ),
            account_refs=account_refs,
        )
        if summary_only:
            for card in cards:
                card.pop("session", None)
                card.pop("accountHabits", None)
                card.pop("taskStack", None)
                card.pop("notices", None)
        response = {
            "ok": True,
            "accounts": cards,
        }
        if "summary" in body:
            response["summary"] = summary_only
        return response

    def _areas_route(
        self,
        body: Dict[str, Any],
        context: Dict[str, Any],
    ) -> Dict[str, Any]:
        local = project_area_catalog(body)
        if local["areas"]:
            return {**local, "source": "local-cache"}
        platform_key = str(local["platformKey"])
        # A host that keeps its own copy (the desktop reads one off disk) passes
        # it in above.  Android had nowhere to keep one, so it always sent an
        # empty catalog and every call fell through to the cloud, reading the
        # whole platform directory for a list of servers that changes about
        # monthly - and throwing the answer away again.  The core keeps the copy
        # now, so neither host has to, and the cloud is only asked when nothing
        # has ever been seen.
        cached = self._read_area_catalog_cache(platform_key)
        if cached:
            projected = project_area_catalog({
                "platformKey": platform_key,
                "areas": cached,
            })
            if projected["areas"]:
                return {**projected, "source": "local-cache"}
        port = self._ports.cloud_shared_data
        if port is None or not bool(port.configured()):
            return {
                **local,
                "source": "unavailable",
                "error": "共享云端区服目录未配置",
            }
        try:
            response = port.exchange({
                "method": "POST",
                "path": "/v1/servers/directory/query",
                "body": {"platformKey": platform_key},
            })
            if not isinstance(response, dict):
                raise RuntimeError("共享区服目录传输未返回对象")
            status = int(response.get("status") or 0)
            payload = response.get("body")
            if not isinstance(payload, dict):
                raise RuntimeError("共享区服目录响应正文无效")
            if not 200 <= status < 300 or payload.get("ok") is not True:
                raise RuntimeError(
                    str(payload.get("error") or f"共享区服目录 HTTP {status}")
                )
            projected = project_area_catalog({
                "platformKey": platform_key,
                "areas": payload.get("areas") or [],
                "updatedAt": payload.get("updatedAt"),
            })
            # Remember it, or the next call pays for the same table read again.
            self._write_area_catalog_cache(platform_key, projected["areas"])
            return {**projected, "source": "cloud-shared-data"}
        except Exception as error:
            self._ports.logs.write({
                "level": "warn",
                "source": "cloud-shared-data",
                "message": f"读取共享区服目录失败：{error}",
            })
            return {
                **local,
                "source": "unavailable",
                "error": f"读取共享云端区服目录失败：{error}",
            }

